import{_ as r,o as t,c as a,a5 as s}from"./chunks/framework.CXroN2RO.js";const o="/study/images/graphics/ping-pong-and-history.svg",m=JSON.parse('{"title":"後処理のピンポンバッファとフレーム履歴","description":"","frontmatter":{"title":"後処理のピンポンバッファとフレーム履歴","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"2枚のテクスチャを交互に使い、横・縦ブラーの中間結果や、TAAの前フレーム履歴を渡す。読み書きの競合、履歴の無効化、GPU完了までの保持を扱う。","aliases":["ピンポンバッファ","ping-pong buffer","ダブルバッファ","履歴バッファ","history buffer","temporal history","separable blur","camera cut","UAV"],"verification":"MicrosoftのD3D12仕様、AMD FidelityFXのブラーとカメラカット、Unityのカメラ履歴管理の公式資料に照合（2026-11-07）"}},"headers":[],"relativePath":"graphics/postprocess/ping-pong-and-history.md","filePath":"graphics/postprocess/ping-pong-and-history.md"}'),i={name:"graphics/postprocess/ping-pong-and-history.md"};function n(d,e,c,p,h,l){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="後処理のピンポンバッファとフレーム履歴" tabindex="-1">後処理のピンポンバッファとフレーム履歴 <a class="header-anchor" href="#後処理のピンポンバッファとフレーム履歴" aria-label="Permalink to &quot;後処理のピンポンバッファとフレーム履歴&quot;">​</a></h1><p>画面全体を横方向にぼかし、その結果を縦方向にぼかすとき、各パスは直前の画像を読みながら次の画像を作ります。<strong>ピンポンバッファ</strong>では2枚のテクスチャを用意し、パスを進めるたびに読み取り元と書き込み先を入れ替えます。前フレームの結果を使う時間方向の処理でも同じ配置を使えますが、何をいつまで保持するかは変わります。<a href="/study/graphics/postprocess/render-to-texture.html">テクスチャに描いて次のパスで読む</a></p><figure class="study-figure"><img src="'+o+'" alt="上段では1フレーム内で横ブラーがAを読みBへ書き、縦ブラーがBを読みAへ書く。下段ではフレームnが履歴H0を読みH1に更新し、次のフレームがH1を読んでH0に更新する。H1はフレームの境界を越えて保持する。" width="760" height="480" loading="lazy"><figcaption>2枚の役割を交互に変える例です。縦ブラーの後にAに残る画像は同じフレームで使い、時間方向の処理で得た履歴は次のフレームに渡します。<a href="/study/images/graphics/ping-pong-and-history.svg" target="_blank" rel="noopener noreferrer">ピンポンと履歴の図を拡大</a></figcaption></figure><h2 id="_1フレーム内で中間画像を渡す" tabindex="-1">1フレーム内で中間画像を渡す <a class="header-anchor" href="#_1フレーム内で中間画像を渡す" aria-label="Permalink to &quot;1フレーム内で中間画像を渡す&quot;">​</a></h2><p>横と縦に分けて処理できるガウシアンブラーを例にします。ここではシーンを描いた画像をAに置き、Aの元の内容は横ブラーが最後に使うものとします。ピクセルシェーダーによる2パスを、同じD3D12のDIRECTキューへ順に提出します。<a href="https://gpuopen.com/manuals/fidelityfx_sdk/samples/blur/" target="_blank" rel="noreferrer">AMDの分離型ガウシアンブラーのサンプル</a> · <a href="/study/graphics/optimization/d3d12-resource-barriers.html">D3D12のリソースバリア</a></p><table tabindex="0"><thead><tr><th>パス</th><th>シェーダーが読む画像</th><th>レンダーターゲットへ書く画像</th></tr></thead><tbody><tr><td>横ブラー</td><td>Aのシーン画像</td><td>Bの横ブラー結果</td></tr><tr><td>縦ブラー</td><td>Bの横ブラー結果</td><td>Aの完成画像</td></tr></tbody></table><p>横ブラーの前にAを <code>PIXEL_SHADER_RESOURCE</code> にし、Bを <code>RENDER_TARGET</code> にします。縦ブラーの前にはBを <code>RENDER_TARGET</code> から <code>PIXEL_SHADER_RESOURCE</code> へ、Aを逆向きに遷移させます。パスを記録するときは、読み取り用のSRVと書き込み用のRTVも選び直します。たとえばブルーム合成が元のシーン画像を読むなら、その画像は最後まで保持し、ブラー用のAとBを別に用意します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/using-resource-barriers-to-synchronize-resource-states-in-direct3d-12" target="_blank" rel="noreferrer">Microsoftのリソース状態と遷移の解説</a> · <a href="/study/graphics/optimization/render-pass-attachments.html">アタッチメントの読み込みと保存</a></p><h2 id="読み取り元と書き込み先が重なる範囲を確認する" tabindex="-1">読み取り元と書き込み先が重なる範囲を確認する <a class="header-anchor" href="#読み取り元と書き込み先が重なる範囲を確認する" aria-label="Permalink to &quot;読み取り元と書き込み先が重なる範囲を確認する&quot;">​</a></h2><p>D3D12の従来のリソース状態では、同じサブリソースに <code>RENDER_TARGET</code> とシェーダー読み取りの状態を同時に指定できません。たとえばmip 0を読みmip 1に書く場合は、SRVの範囲をmip 0に絞り、mip 1だけをRTVで指定し、それぞれの状態を管理します。ブラーのように、出力画素ごとに元の近傍を読む処理では、入力と出力に別の範囲を用意すると、全画素が同じ元画像を参照できます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/using-resource-barriers-to-synchronize-resource-states-in-direct3d-12#readwrite-resource-state-restrictions" target="_blank" rel="noreferrer">Microsoftの読み取りと書き込みの制約</a> · <a href="/study/graphics/texture/dds-and-subresources.html">テクスチャのサブリソース</a></p><p>計算シェーダーで同じUAVを読み書きする方式もあります。たとえば各スレッドが自分の担当する1画素だけを読み書きし、他のスレッドがその画素を参照しない色変換なら、元の場所に結果を書けます。読み取りに使うUAVの形式はデバイスで対応を確認します。近傍を直接読むブラーでは、別スレッドが書き換えた画素を先に読んでしまうことがあります。グループ同期はそのグループ内に限られ、ディスパッチ間のUAVバリアは前後のGPU処理の順序を指定します。処理を同じ場所で行えるかは、各スレッドがどの値を読み、誰がその値を書き換えるかで決まります。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/typed-unordered-access-view-loads" target="_blank" rel="noreferrer">Microsoftの型付きUAVロード</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3dhlsl/groupmemorybarrierwithgroupsync" target="_blank" rel="noreferrer">HLSLのグループ同期</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/ns-d3d12-d3d12_resource_uav_barrier" target="_blank" rel="noreferrer">D3D12のUAVバリア</a></p><h2 id="次のフレームが読む履歴を作る" tabindex="-1">次のフレームが読む履歴を作る <a class="header-anchor" href="#次のフレームが読む履歴を作る" aria-label="Permalink to &quot;次のフレームが読む履歴を作る&quot;">​</a></h2><p>TAAのような時間方向の処理では、今フレームの色に加えて、以前の描画を蓄積した<strong>履歴</strong>を読みます。フレームnで履歴H0を読み、モーションベクターを使って現在の画素位置へ再投影し、今フレームの色と合成してH1に書きます。フレームn+1ではH1が読み取り元になり、H0が書き込み先になります。以前のカメラ行列や画像の有効領域など、履歴を解釈するために使う情報も、その履歴を作ったフレームに対応付けます。<a href="/study/graphics/postprocess/taa.html">TAAの再投影と蓄積</a> · <a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/temporal-super-resolution-frequently-asked-questions-for-unreal-engine" target="_blank" rel="noreferrer">Unreal EngineのTSR履歴</a></p><p>最初のフレームやカメラが急に切り替わったフレームでは、以前の履歴を無効にし、現在のデータから次の履歴を作ります。解像度変更で履歴テクスチャを作り直す場合も、以前の画像を新しい座標で扱う処理がなければ同じ手順を取ります。動的解像度を扱う設計では、履歴のサイズを固定する方法や、前フレームの有効領域に合わせて読み取り位置を調整する方法もあります。<a href="https://gpuopen.com/manuals/fsr_sdk/techniques/super-resolution-temporal/#camera-jump-cuts" target="_blank" rel="noreferrer">AMD FSR 2のカメラカットとリセット</a> · <a href="https://docs.unity3d.com/Packages/com.unity.render-pipelines.core@17.0/manual/rthandle-system-using.html" target="_blank" rel="noreferrer">Unityのカメラ別履歴と動的解像度</a></p><h2 id="履歴の持ち主とgpu上での寿命を追う" tabindex="-1">履歴の持ち主とGPU上での寿命を追う <a class="header-anchor" href="#履歴の持ち主とgpu上での寿命を追う" aria-label="Permalink to &quot;履歴の持ち主とGPU上での寿命を追う&quot;">​</a></h2><p>履歴の入れ替えはカメラやビューごとの処理に合わせます。たとえばメインカメラとミニマップを別の頻度で描くなら、それぞれに「最後に作った有効な履歴」を持たせます。スワップチェーンの画像番号や、CPUが記録用メモリを使い回すフレームスロットは、別の対象を指します。<a href="https://docs.unity3d.com/Packages/com.unity.render-pipelines.core@17.0/manual/rthandle-system-using.html" target="_blank" rel="noreferrer">Unityのカメラ別履歴</a> · <a href="/study/graphics/optimization/swap-chain-and-vsync.html">スワップチェーンとVSync</a> · <a href="/study/graphics/optimization/parallel-command-recording.html">フレームスロットとフェンス</a></p><p>CPUが次のフレームを記録している間も、GPUは先の履歴を使っていることがあります。固定の2枚を同じキューで順に使う場合は、書き込みから読み取りへ、読み取りから次の書き込みへと、実行順と状態遷移を組みます。別キューなら、以前の書き込みや読み取りが完了する順序も <code>Signal</code> と <code>Wait</code> でつなぎます。CPUが古い履歴を無効と判断しても、提出済みの処理がそのテクスチャや記述子を使い終えるまでは保持します。リサイズで古いテクスチャを解放するときも、最後のGPU参照の完了をフェンスで確認します。<a href="/study/graphics/optimization/gpu-queue-synchronization.html">D3D12のキュー間同期</a> · <a href="/study/graphics/optimization/gpu-resource-lifetime.html">GPUリソースの寿命</a></p>',16)])])}const g=r(i,[["render",n]]);export{m as __pageData,g as default};
